  translate([p[0], p[1], gear_z]) {
    spur_gear(circ_pitch=circ_pitch, teeth=teeth, thickness=gear_thk, gear_spin=spin_barrel);
    up(gear_thk / 2 - 0.5)
      cyl(h=3.2, r=pr(teeth) * 0.78, rounding2=1.2, anchor=BOTTOM);
